// Stopwords and noise words to ignore in semantic fuzzy matching
const STOPWORDS = new Set([
  'a', 'an', 'the', 'is', 'are', 'am', 'was', 'were', 'be', 'this', 'that', 'these', 'those',
  'it', 'its', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'and', 'or', 'do', 'does',
  'यह', 'ये', 'वह', 'वे', 'है', 'हैं', 'था', 'थे', 'थी', 'का', 'के', 'की', 'में', 'पर', 'को',
  'से', 'द्वारा', 'और', 'या', 'एक', 'करें', 'कीजिए'
]);

export function normalizeText(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[.,!?;:"'()|᱾᱿]/g, '')
    .replace(/\s+/g, ' ');
}

function getSignificantTokens(text: string): string[] {
  const normalized = normalizeText(text);
  return normalized
    .split(' ')
    .filter(token => token.length > 0 && !STOPWORDS.has(token));
}

// Pre-indexed Hash Maps for instant O(1) Lookups
const EN_MAP = new Map<string, SantaliDatasetEntry>();
const HI_MAP = new Map<string, SantaliDatasetEntry>();
const SAT_MAP = new Map<string, SantaliDatasetEntry>();
const ROMAN_MAP = new Map<string, SantaliDatasetEntry>();

const WORD_EN_MAP = new Map<string, VocabularyWord>();
const WORD_HI_MAP = new Map<string, VocabularyWord>();
const WORD_SAT_MAP = new Map<string, VocabularyWord>();

for (const entry of SANTALI_DATASET) {
  if (entry.en) EN_MAP.set(normalizeText(entry.en), entry);
  if (entry.hi) HI_MAP.set(normalizeText(entry.hi), entry);
  if (entry.sat) SAT_MAP.set(entry.sat.trim(), entry);
  if (entry.roman) ROMAN_MAP.set(normalizeText(entry.roman), entry);
}

for (const word of CORE_VOCABULARY) {
  WORD_EN_MAP.set(word.en.toLowerCase().trim(), word);
  WORD_HI_MAP.set(word.hi.toLowerCase().trim(), word);
  WORD_SAT_MAP.set(word.sat.trim(), word);
}

/**
 * Direct lookup for single vocabulary words to prevent full sentence repetition
 */
export function lookupWord(input: string, sourceLang: string): VocabularyWord | null {
  const clean = input.toLowerCase().trim().replace(/[.,!?;:"'()]/g, '');
  if (!clean) return null;

  if (sourceLang === 'eng') {
    return WORD_EN_MAP.get(clean) || null;
  }
  if (sourceLang === 'hin') {
    return WORD_HI_MAP.get(clean) || null;
  }
  if (sourceLang === 'sat') {
    return WORD_SAT_MAP.get(input.trim()) || null;
  }
  return null;
}

/**
 * Intelligent semantic fuzzy matcher for sentences and phrases
 */
export function findSantaliMatch(
  query: string, 
  sourceLang: 'eng' | 'hin' | 'sat'
): { match: SantaliDatasetEntry; confidence: number } | null {
  if (!query || !query.trim()) return null;

  const cleanQuery = normalizeText(query);
  const queryTokens = getSignificantTokens(query);

  // 1. Exact Match
  if (sourceLang === 'eng') {
    const exact = EN_MAP.get(cleanQuery);
    if (exact) return { match: exact, confidence: 1.0 };
  } else if (sourceLang === 'hin') {
    const exact = HI_MAP.get(cleanQuery);
    if (exact) return { match: exact, confidence: 1.0 };
  } else if (sourceLang === 'sat') {
    const exactSat = SAT_MAP.get(query.trim()) || ROMAN_MAP.get(cleanQuery);
    if (exactSat) return { match: exactSat, confidence: 1.0 };
  }

  // 2. Token Jaccard Similarity Fuzzy Match
  if (queryTokens.length === 0) return null;

  let bestEntry: SantaliDatasetEntry | null = null;
  let bestScore = 0;

  for (const item of SANTALI_DATASET) {
    const targetText = sourceLang === 'eng' ? item.en : sourceLang === 'hin' ? item.hi : item.sat;
    const targetTokens = getSignificantTokens(targetText);

    if (targetTokens.length === 0) continue;

    // Calculate token intersection
    let intersection = 0;
    for (const qToken of queryTokens) {
      if (targetTokens.some(t => t === qToken || (qToken.length >= 4 && t.includes(qToken)))) {
        intersection++;
      }
    }

    const union = new Set([...queryTokens, ...targetTokens]).size;
    const jaccard = union > 0 ? intersection / union : 0;

    // Substring bonus
    const normTarget = normalizeText(targetText);
    let score = jaccard;
    if (normTarget.includes(cleanQuery) || cleanQuery.includes(normTarget)) {
      score = Math.max(score, 0.75 + (jaccard * 0.25));
    }

    if (score > bestScore) {
      bestScore = score;
      bestEntry = item;
      if (bestScore >= 0.95) break; // Early exit on near-exact
    }
  }

  // Require high confidence: single-word queries need ≥ 0.90, multi-word ≥ 0.65
  const minThreshold = queryTokens.length <= 1 ? 0.90 : 0.65;
  if (bestEntry && bestScore >= minThreshold) {
    return { match: bestEntry, confidence: Math.min(bestScore, 0.98) };
  }

  return null;
}
